using System; using Inu.Kernel.Drivers; namespace Inu.Samples.PciDriver; public static unsafe class Sample { public static Boolean Register(out KernelDriverHandle handle){ var rule=new KernelDriverMatchRule(KernelDeviceBus.Pci,true,0,false,0,false,0x020000U,0xFF0000U); var cb=new KernelDriverCallbacks(&Probe,&Start,&Stop,&Remove,null); var caps=new KernelDriverCapabilityDeclaration(KernelDriverCapability.PciConfig|KernelDriverCapability.Mmio|KernelDriverCapability.Interrupt); return KernelDrivers.RegisterDriver("sample-pci",rule,cb,caps,out handle);} private static Boolean Probe(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Start(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Stop(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Remove(KernelDriverDeviceContext* c)=>c!=null; }
